mapper.insert:
INSERT INTO tb_role_permission (role_seq, perm_seq, action_code, data_scope, created_by) SELECT #{roleSeq}, p.perm_seq, v.action_code, v.data_scope, #{createdBy} FROM (
SELECT #{row.permId} AS perm_id, #{row.actionCode} AS action_code, #{row.dataScope} AS data_scope
) AS v JOIN tb_permission p ON p.perm_id = v.perm_id

mapper.select:
SELECT COUNT(DISTINCT rp.role_seq)
  FROM tb_role_permission rp
  JOIN tb_role r       ON r.role_seq = rp.role_seq AND r.use_yn = 'Y'
  JOIN tb_permission p ON p.perm_seq = rp.perm_seq AND p.use_yn = 'Y'
 WHERE rp.role_seq <> #{exceptRoleSeq}
   AND p.perm_id = #{permId}
   AND rp.action_code = #{actionCode}
